// Loads the built chat page in a bare WKWebView with a stand-in host, then
// hands WebKit a Finder-shaped file drop at a point of the page.
#import <AppKit/AppKit.h>
#import <WebKit/WebKit.h>
#include "fake.inc"
int main(int argc, char **argv) { @autoreleasepool {
  NSString *page = @(argv[1]), *file = @(argv[2]), *hostJs = @(argv[5]), *snap = @(argv[6]);
  double fx = atof(argv[3]), fy = atof(argv[4]);
  [NSApplication sharedApplication];
  [NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];
  NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(100,100,430,900) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];
  WKWebViewConfiguration *cfg = [WKWebViewConfiguration new];
  NSString *js = [NSString stringWithContentsOfFile:hostJs encoding:NSUTF8StringEncoding error:nil];
  [cfg.userContentController addUserScript:[[WKUserScript alloc] initWithSource:js injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:YES]];
  WKWebView *wv = [[WKWebView alloc] initWithFrame:NSMakeRect(0,0,430,900) configuration:cfg];
  w.contentView = wv; [w orderFront:nil];
  NSURL *url = [NSURL fileURLWithPath:page];
  [wv loadFileURL:url allowingReadAccessToURL:[url URLByDeletingLastPathComponent]];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 3*NSEC_PER_SEC), dispatch_get_main_queue(), ^{
    [wv evaluateJavaScript:@"document.querySelector('.composer') ? 'composer shown, ' + document.elementFromPoint(innerWidth/2, innerHeight*0.4)?.className : 'no composer'" completionHandler:^(id r, NSError *e){ printf("before: %s\n", [[r description] UTF8String] ?: "?"); }];
    NSPasteboard *pb = [NSPasteboard pasteboardWithName:NSPasteboardNameDrag]; [pb clearContents];
    [pb writeObjects:@[[NSURL fileURLWithPath:file]]]; [pb setPropertyList:@[file] forType:@"NSFilenamesPboardType"];
    FakeDrag *d = [FakeDrag new]; d.pb = pb; d.win = w; d.loc = [wv convertPoint:NSMakePoint(fx*430, fy*900) toView:nil];
    [wv draggingEntered:d];
    NSDragOperation op = 0;
    for (int i = 0; i < 5; i++) { [[NSRunLoop mainRunLoop] runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.2]]; op = [wv draggingUpdated:d]; }
    printf("drag operation the page offers: %lu (0 = none, 1 = copy, 16 = move)\n", (unsigned long)op);
    if (op) { [wv performDragOperation:d]; [wv concludeDragOperation:d]; printf("dropped\n"); }
    else { [wv draggingExited:d]; printf("not dropped: macOS does not drop where the operation is none\n"); }
    [[NSRunLoop mainRunLoop] runUntilDate:[NSDate dateWithTimeIntervalSinceNow:2]];
    [wv evaluateJavaScript:@"JSON.stringify({page: location.pathname.split('/').pop(), sent: window.__sent || 'page gone'})" completionHandler:^(id r, NSError *e){
      printf("after: %s\n", [[r description] UTF8String] ?: [[e description] UTF8String]);
      [wv takeSnapshotWithConfiguration:nil completionHandler:^(NSImage *img, NSError *e2) {
        NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:img.TIFFRepresentation];
        [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:snap atomically:YES];
        exit(0);
      }];
    }];
  });
  [NSApp run];
}}
EOF
